import React, { useState, useEffect } from 'react';
import { Button, Form } from 'react-bootstrap';
import axios from 'axios';

const API_URL = 'http://localhost:5000/api';

function MemoryManagement() {
  const [algorithm, setAlgorithm] = useState('LRU');
  const [numFrames, setNumFrames] = useState(3);
  const [referenceString, setReferenceString] = useState('');
  const [frames, setFrames] = useState([]);
  const [pageFaults, setPageFaults] = useState(0);
  const [pageHits, setPageHits] = useState(0);
  const [executionSteps, setExecutionSteps] = useState([]);
  const [stats, setStats] = useState(null);

  useEffect(() => {
    // Clear memory data on mount
    setFrames([]);
    setPageFaults(0);
    setPageHits(0);
    setExecutionSteps([]);
    setStats(null);
  }, []);

  const simulatePageReplacement = () => {
    if (!referenceString.trim()) {
      alert('Please enter a page reference string!');
      return;
    }

    // Parse reference string (comma or space separated)
    const pages = referenceString
      .split(/[\s,]+/)
      .map(p => parseInt(p.trim()))
      .filter(p => !isNaN(p));

    if (pages.length === 0) {
      alert('Invalid page reference string!');
      return;
    }

    let frameArray = Array(numFrames).fill(null);
    let faults = 0;
    let hits = 0;
    let steps = [];
    let queue = []; // For FIFO
    let recentlyUsed = []; // For LRU

    pages.forEach((page, index) => {
      let framesCopy = [...frameArray];
      let isFault = false;

      if (frameArray.includes(page)) {
        // Page Hit
        hits++;
        if (algorithm === 'LRU') {
          // Update recently used
          recentlyUsed = recentlyUsed.filter(p => p !== page);
          recentlyUsed.push(page);
        }
      } else {
        // Page Fault
        faults++;
        isFault = true;

        const emptyIndex = frameArray.indexOf(null);
        
        if (emptyIndex !== -1) {
          // Empty frame available
          frameArray[emptyIndex] = page;
          if (algorithm === 'FIFO') queue.push(page);
          if (algorithm === 'LRU') recentlyUsed.push(page);
        } else {
          // Need to replace a page
          let replaceIndex = 0;

          if (algorithm === 'FIFO') {
            const pageToReplace = queue.shift();
            replaceIndex = frameArray.indexOf(pageToReplace);
            queue.push(page);
          } else if (algorithm === 'LRU') {
            const lruPage = recentlyUsed.shift();
            replaceIndex = frameArray.indexOf(lruPage);
            recentlyUsed.push(page);
          } else if (algorithm === 'OPTIMAL') {
            // Find page not used for longest time in future
            let farthest = -1;
            let replaceIdx = 0;

            for (let i = 0; i < frameArray.length; i++) {
              let j;
              for (j = index + 1; j < pages.length; j++) {
                if (frameArray[i] === pages[j]) {
                  if (j > farthest) {
                    farthest = j;
                    replaceIdx = i;
                  }
                  break;
                }
              }
              if (j === pages.length) {
                replaceIdx = i;
                break;
              }
            }
            replaceIndex = replaceIdx;
          }

          frameArray[replaceIndex] = page;
        }
      }

      steps.push({
        step: index + 1,
        page: page,
        frames: [...frameArray],
        isFault: isFault,
        status: isFault ? 'Fault' : 'Hit'
      });
    });

    setFrames(frameArray);
    setPageFaults(faults);
    setPageHits(hits);
    setExecutionSteps(steps);
    
    const hitRatio = ((hits / pages.length) * 100).toFixed(2);
    const faultRatio = ((faults / pages.length) * 100).toFixed(2);

    setStats({
      totalReferences: pages.length,
      pageFaults: faults,
      pageHits: hits,
      hitRatio: hitRatio,
      faultRatio: faultRatio,
      algorithm: algorithm
    });
  };

  const clearSimulation = () => {
    setReferenceString('');
    setFrames([]);
    setPageFaults(0);
    setPageHits(0);
    setExecutionSteps([]);
    setStats(null);
  };

  return (
    <div style={{ 
      height: '100%', 
      display: 'flex', 
      gap: '15px', 
      padding: '15px',
      background: 'linear-gradient(135deg, #BBE1FA 0%, #3282B8 100%)',
      overflow: 'hidden'
    }}>
      
      {/* LEFT SECTION - 25% - Configuration */}
      <div style={{ 
        width: '25%', 
        padding: '15px', 
        overflowY: 'auto',
        background: 'linear-gradient(180deg, #ffffff 0%, #BBE1FA 100%)',
        borderRadius: '20px',
        boxShadow: '0 8px 32px rgba(15, 76, 117, 0.2)',
        border: '2px solid rgba(50, 130, 184, 0.3)'
      }}
      className="custom-scrollbar">
        
        <h2 style={{ 
          textAlign: 'center', 
          marginBottom: '15px',
          fontSize: '1.3rem',
          fontWeight: '800',
          background: 'linear-gradient(135deg, #0F4C75 0%, #3282B8 100%)',
          WebkitBackgroundClip: 'text',
          WebkitTextFillColor: 'transparent',
          textShadow: '0 2px 10px rgba(50, 130, 184, 0.3)'
        }}>
          🧠 Memory Management
        </h2>

        <div style={{ 
          height: '2px', 
          background: 'linear-gradient(90deg, #0F4C75 0%, #3282B8 100%)',
          margin: '12px 0',
          borderRadius: '2px'
        }} />

        <h3 className="mb-2" style={{ 
          color: '#2d3748', 
          borderBottom: '2px solid #3282B8', 
          paddingBottom: '6px',
          fontSize: '1.1rem',
          fontWeight: '700',
          background: 'linear-gradient(135deg, #3282B8 0%, #0F4C75 100%)',
          WebkitBackgroundClip: 'text',
          WebkitTextFillColor: 'transparent'
        }}>
          ⚙️ Configuration
        </h3>

        <Form style={{ marginBottom: '15px' }}>
          <Form.Group className="mb-2">
            <Form.Label style={{ fontSize: '0.8rem', fontWeight: 'bold', color: '#2d3748' }}>
              Algorithm
            </Form.Label>
            <Form.Select 
              value={algorithm} 
              onChange={(e) => setAlgorithm(e.target.value)}
              style={{ 
                fontSize: '0.8rem',
                border: '2px solid #3282B8',
                borderRadius: '8px'
              }}
            >
              <option value="FIFO">FIFO (First-In-First-Out)</option>
              <option value="LRU">LRU (Least Recently Used)</option>
              <option value="OPTIMAL">OPTIMAL (Optimal Page Replacement)</option>
            </Form.Select>
          </Form.Group>

          <Form.Group className="mb-2">
            <Form.Label style={{ fontSize: '0.8rem', fontWeight: 'bold', color: '#2d3748' }}>
              Number of Frames
            </Form.Label>
            <Form.Control 
              type="number" 
              min="1" 
              max="10"
              value={numFrames}
              onChange={(e) => setNumFrames(parseInt(e.target.value) || 1)}
              style={{ 
                fontSize: '0.8rem',
                border: '2px solid #3282B8',
                borderRadius: '8px'
              }}
            />
          </Form.Group>

          <Form.Group className="mb-2">
            <Form.Label style={{ fontSize: '0.8rem', fontWeight: 'bold', color: '#2d3748' }}>
              Page Reference String
            </Form.Label>
            <Form.Control 
              as="textarea"
              rows={3}
              placeholder="e.g., 7 0 1 2 0 3 0 4 2 3 0 3 2"
              value={referenceString}
              onChange={(e) => setReferenceString(e.target.value)}
              style={{ 
                fontSize: '0.8rem',
                border: '2px solid #3282B8',
                borderRadius: '8px',
                resize: 'none'
              }}
            />
            <Form.Text style={{ fontSize: '0.65rem', color: '#718096' }}>
              Enter pages separated by spaces or commas
            </Form.Text>
          </Form.Group>
        </Form>

        <Button 
          onClick={simulatePageReplacement}
          style={{ 
            width: '100%', 
            background: 'linear-gradient(135deg, #3282B8 0%, #0F4C75 100%)',
            border: 'none',
            borderRadius: '8px',
            padding: '8px',
            fontSize: '0.85rem',
            fontWeight: 'bold',
            color: 'white',
            boxShadow: '0 4px 15px rgba(50, 130, 184, 0.4)',
            transition: 'all 0.3s',
            transform: 'translateY(0)',
            marginBottom: '8px'
          }}
          onMouseEnter={(e) => {
            e.target.style.transform = 'translateY(-2px)';
            e.target.style.boxShadow = '0 6px 20px rgba(50, 130, 184, 0.6)';
          }}
          onMouseLeave={(e) => {
            e.target.style.transform = 'translateY(0)';
            e.target.style.boxShadow = '0 4px 15px rgba(50, 130, 184, 0.4)';
          }}
        >
          🚀 Run Simulation
        </Button>

        <Button 
          onClick={clearSimulation}
          style={{ 
            width: '100%', 
            background: 'linear-gradient(135deg, #1B262C 0%, #0F4C75 100%)',
            border: 'none',
            borderRadius: '8px',
            padding: '8px',
            fontSize: '0.85rem',
            fontWeight: 'bold',
            color: 'white',
            boxShadow: '0 4px 15px rgba(27, 38, 44, 0.4)',
            transition: 'all 0.3s',
            transform: 'translateY(0)'
          }}
          onMouseEnter={(e) => {
            e.target.style.transform = 'translateY(-2px)';
            e.target.style.boxShadow = '0 6px 20px rgba(27, 38, 44, 0.6)';
          }}
          onMouseLeave={(e) => {
            e.target.style.transform = 'translateY(0)';
            e.target.style.boxShadow = '0 4px 15px rgba(27, 38, 44, 0.4)';
          }}
        >
          🗑️ Clear
        </Button>
      </div>

      {/* RIGHT SECTION - 75% - Visualization */}
      <div style={{ 
        width: '75%', 
        display: 'flex',
        flexDirection: 'column',
        gap: '15px',
        overflowY: 'auto'
      }}
      className="custom-scrollbar">
        
        {/* Statistics Section */}
        {stats && (
          <div style={{ 
            padding: '20px', 
            background: 'linear-gradient(180deg, #ffffff 0%, #BBE1FA 100%)',
            borderRadius: '20px',
            boxShadow: '0 8px 32px rgba(15, 76, 117, 0.2)',
            border: '2px solid rgba(50, 130, 184, 0.3)'
          }}>
            <h3 style={{ 
              marginBottom: '15px',
              fontSize: '1.2rem',
              fontWeight: '800',
              background: 'linear-gradient(135deg, #0F4C75 0%, #3282B8 100%)',
              WebkitBackgroundClip: 'text',
              WebkitTextFillColor: 'transparent'
            }}>
              📊 Statistics
            </h3>

            <div style={{ 
              display: 'grid', 
              gridTemplateColumns: 'repeat(3, 1fr)', 
              gap: '15px',
              fontSize: '0.9rem'
            }}>
              <div style={{ 
                padding: '15px',
                background: 'rgba(187, 225, 250, 0.4)',
                borderRadius: '12px',
                border: '2px solid #3282B8',
                textAlign: 'center'
              }}>
                <div style={{ fontSize: '0.75rem', color: '#718096', marginBottom: '5px' }}>
                  Algorithm
                </div>
                <div style={{ fontSize: '1.3rem', fontWeight: 'bold', color: '#0F4C75' }}>
                  {stats.algorithm}
                </div>
              </div>

              <div style={{ 
                padding: '15px',
                background: 'rgba(187, 225, 250, 0.4)',
                borderRadius: '12px',
                border: '2px solid #3282B8',
                textAlign: 'center'
              }}>
                <div style={{ fontSize: '0.75rem', color: '#718096', marginBottom: '5px' }}>
                  Total References
                </div>
                <div style={{ fontSize: '1.3rem', fontWeight: 'bold', color: '#0F4C75' }}>
                  {stats.totalReferences}
                </div>
              </div>

              <div style={{ 
                padding: '15px',
                background: 'rgba(255, 107, 107, 0.15)',
                borderRadius: '12px',
                border: '2px solid #e53e3e',
                textAlign: 'center'
              }}>
                <div style={{ fontSize: '0.75rem', color: '#718096', marginBottom: '5px' }}>
                  Page Faults
                </div>
                <div style={{ fontSize: '1.3rem', fontWeight: 'bold', color: '#e53e3e' }}>
                  {stats.pageFaults}
                </div>
              </div>

              <div style={{ 
                padding: '15px',
                background: 'rgba(72, 187, 120, 0.15)',
                borderRadius: '12px',
                border: '2px solid #38a169',
                textAlign: 'center'
              }}>
                <div style={{ fontSize: '0.75rem', color: '#718096', marginBottom: '5px' }}>
                  Page Hits
                </div>
                <div style={{ fontSize: '1.3rem', fontWeight: 'bold', color: '#38a169' }}>
                  {stats.pageHits}
                </div>
              </div>

              <div style={{ 
                padding: '15px',
                background: 'rgba(72, 187, 120, 0.2)',
                borderRadius: '12px',
                border: '2px solid #38a169',
                textAlign: 'center'
              }}>
                <div style={{ fontSize: '0.75rem', color: '#718096', marginBottom: '5px' }}>
                  Hit Ratio
                </div>
                <div style={{ fontSize: '1.3rem', fontWeight: 'bold', color: '#38a169' }}>
                  {stats.hitRatio}%
                </div>
              </div>

              <div style={{ 
                padding: '15px',
                background: 'rgba(255, 107, 107, 0.2)',
                borderRadius: '12px',
                border: '2px solid #e53e3e',
                textAlign: 'center'
              }}>
                <div style={{ fontSize: '0.75rem', color: '#718096', marginBottom: '5px' }}>
                  Fault Ratio
                </div>
                <div style={{ fontSize: '1.3rem', fontWeight: 'bold', color: '#e53e3e' }}>
                  {stats.faultRatio}%
                </div>
              </div>
            </div>
          </div>
        )}

        {/* Execution Steps Table */}
        <div style={{ 
          padding: '20px', 
          background: 'linear-gradient(180deg, #ffffff 0%, #BBE1FA 100%)',
          borderRadius: '20px',
          boxShadow: '0 8px 32px rgba(15, 76, 117, 0.2)',
          border: '2px solid rgba(50, 130, 184, 0.3)'
        }}>
          <h3 style={{ 
            marginBottom: '15px',
            fontSize: '1.2rem',
            fontWeight: '800',
            background: 'linear-gradient(135deg, #0F4C75 0%, #3282B8 100%)',
            WebkitBackgroundClip: 'text',
            WebkitTextFillColor: 'transparent'
          }}>
            📋 Execution Timeline
          </h3>

          {executionSteps.length === 0 ? (
            <div style={{
              display: 'flex',
              justifyContent: 'center',
              alignItems: 'center',
              height: '300px',
              fontSize: '1rem',
              color: '#718096',
              fontStyle: 'italic'
            }}>
              Run simulation to see page replacement execution
            </div>
          ) : (
            <div style={{ overflowX: 'auto' }}>
              <table style={{ 
                width: '100%', 
                borderCollapse: 'collapse',
                fontSize: '0.85rem'
              }}>
                <thead>
                  <tr style={{ 
                    background: 'linear-gradient(135deg, #3282B8 0%, #0F4C75 100%)',
                    color: 'white'
                  }}>
                    <th style={{ padding: '10px', border: '1px solid #0F4C75' }}>Step</th>
                    <th style={{ padding: '10px', border: '1px solid #0F4C75' }}>Page</th>
                    {Array(numFrames).fill(0).map((_, i) => (
                      <th key={i} style={{ padding: '10px', border: '1px solid #0F4C75' }}>
                        Frame {i}
                      </th>
                    ))}
                    <th style={{ padding: '10px', border: '1px solid #0F4C75' }}>Status</th>
                  </tr>
                </thead>
                <tbody>
                  {executionSteps.map((step, idx) => (
                    <tr key={idx} style={{ 
                      background: step.isFault 
                        ? 'rgba(255, 107, 107, 0.1)' 
                        : 'rgba(72, 187, 120, 0.1)'
                    }}>
                      <td style={{ 
                        padding: '8px', 
                        border: '1px solid #BBE1FA',
                        textAlign: 'center',
                        fontWeight: 'bold'
                      }}>
                        {step.step}
                      </td>
                      <td style={{ 
                        padding: '8px', 
                        border: '1px solid #BBE1FA',
                        textAlign: 'center',
                        fontWeight: 'bold',
                        background: 'linear-gradient(135deg, #BBE1FA 0%, #3282B8 30%)',
                        color: '#1B262C'
                      }}>
                        {step.page}
                      </td>
                      {step.frames.map((frame, fi) => (
                        <td key={fi} style={{ 
                          padding: '8px', 
                          border: '1px solid #BBE1FA',
                          textAlign: 'center',
                          fontWeight: frame !== null ? 'bold' : 'normal',
                          color: frame !== null ? '#0F4C75' : '#cbd5e0'
                        }}>
                          {frame !== null ? frame : '-'}
                        </td>
                      ))}
                      <td style={{ 
                        padding: '8px', 
                        border: '1px solid #BBE1FA',
                        textAlign: 'center',
                        fontWeight: 'bold',
                        color: step.isFault ? '#e53e3e' : '#38a169'
                      }}>
                        {step.status}
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

export default MemoryManagement;
